window.kbPageData["views/entry/k-4aa308d0488924b5"] = {"key":"entry/k-4aa308d0488924b5","state":{"route":"entry/k-4aa308d0488924b5"},"node":{"id":"k-4aa308d0488924b5","mode":"k","title":"否定后件式","type":"原理与机制","domain":"形式逻辑","reading":"","intro":"","priority":100,"aliases":["充分条件假言推理的否定后件式"],"qs":["国考 2023 行政执法 行测#110","江苏 2023 A类 行测#105"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"repeatPositions":0,"reviewSet":"多题条目","independentCount":2,"directorySummary":"否定后件式是由“若P则Q”和“Q不成立”推出“P不成立”的有效推理形式。","review":{"title":"否定后件式","type":"原理与机制","definition":"否定后件式是由“若P则Q”和“Q不成立”推出“P不成立”的有效推理形式。","explanation":"在“若P则Q”中，Q是P成立的必要条件。用“只有Q，才P”表述时，条件关系同样是“若P则Q”。Q成立时，P仍可能成立或不成立。","basis":"据关联原题和解析编释。","references":[],"related":["k-3a208c42ed1b69b4"],"examFocus":{"国考 2023 行政执法 行测#110":"结合部门间值班的先后关系和日期限制，判断部分部门不值班时哪些排班仍然可行。","江苏 2023 A类 行测#105":"在每人点两道菜且搭配互异的条件下，检验一道菜没点时会怎样约束其他选菜。"}},"aspects":[{"title":"由必要条件不成立排除前件","uses":[{"unit":"Q1","role":"解题依据","use":"本题 中，安排研发值班要求次日安排后勤值班。六天均未安排后勤，因此排除研发。再排除财务和第二天不能值班的法务，可知第二天只能安排销售或人事，对应C项。","evidence":"若安排研发部门的人值班，则只能安排在后勤部门的人值班的前一天。","qids":["国考 2023 行政执法 行测#110"]},{"unit":"Q2","role":"解题依据","use":"本题 中，假设丙没点清蒸鲈鱼，依条件（4）可排除丙点芹菜肉丝和毛豆仔鸡，丙便凑不够两道菜。因而丙、乙、丁都点清蒸鲈鱼，甲没点。由条件（1）再排除丁点芹菜肉丝，结合乙还点毛豆仔鸡和每人搭配互异，丙只能搭配芹菜肉丝，对应C项。","evidence":"根据甲不点清蒸鲈鱼以及条件（1），可以推出丁不点芹菜肉丝","qids":["江苏 2023 A类 行测#105"]}]}]},"questions":{"国考 2023 行政执法 行测#110":{"paper":"国考 2023 行政执法 行测","n":110,"mod":"判断推理","src":["857378cf496f27296500.pdf",21],"asrc":["d23139fe5a0fb3115135.pdf",36],"card":"ea737e83db3950d310b99efe","links":[{"id":"k-4aa308d0488924b5","role":"解题依据","why":"研发值班必以后勤值班为条件，否定后件可推出研发也不值班。"}]},"江苏 2023 A类 行测#105":{"paper":"江苏 2023 A类 行测","n":105,"mod":"判断推理","src":["22304fe4c340e19d7902.pdf",22],"asrc":["be17f9afe070cf13a0fb.pdf",33],"card":"2d2be77a847debe2f3113f73","links":[{"id":"k-4aa308d0488924b5","role":"解题依据","why":"由甲不点清蒸鲈鱼否定后件，从而排除丁点芹菜肉丝。"}]}},"terms":{"k-3a208c42ed1b69b4":{"id":"k-3a208c42ed1b69b4","mode":"k","type":"原理与机制","title":"逆否等价","qs":[],"count":5}},"references":{},"topics":[],"units":{"k-4aa308d0488924b5":[["国考 2023 行政执法 行测#110"],["江苏 2023 A类 行测#105"]]}};
